-- 프로토타입 위키(3장) → wiki_pages 일괄 이식. 한 번만 실행하세요(재실행 시 id 충돌 오류가 나면 이미 실행된 것).
insert into wiki_pages (id, user_id, section, title, definition, points, flagged)
select v.id, u.id, v.section, v.title, v.definition, v.points, v.flagged
from (values
  ('af099b2a-2436-5f06-85b3-93a80722553b'::uuid, '3장 · 1절 · 조적공사 · 벽돌의종류', '점토벽돌', '점토를 성형·소성한 벽돌. 치장(적벽돌)·구조 겸용의 전통 재료.', '["품질 지표: 압축강도·흡수율(종별 기준 ※확인). 소성이 잘될수록 흡수율 낮고 강함."]'::jsonb, true),
  ('a4613c9d-0383-51d0-93c1-1a81092bc328'::uuid, '3장 · 1절 · 조적공사 · 벽돌의종류', '시멘트벽돌', '시멘트+골재를 가압 성형·양생한 벽돌. 저렴 — 칸막이·치장 바탕용. 흡수율 크고 백화에 취약.', '[]'::jsonb, false),
  ('9b2f58c8-a16a-5a78-b37a-a4ce5cc9bf5c'::uuid, '3장 · 1절 · 조적공사 · 벽돌의종류', '내화벽돌', '내화점토로 만든 고온용 벽돌(굴뚝·난로·소각로).', '["쌓을 때 일반 모르타르가 아닌 내화 모르타르 사용, 물축임 하지 않음 — ''내화벽돌은 물 안 축인다''가 시험 포인트."]'::jsonb, false),
  ('87724425-3884-575b-a679-b2dc8199adaf'::uuid, '3장 · 1절 · 조적공사 · 벽돌의종류', '경량벽돌 · 다공벽돌', '기공을 넣어 가볍게 만든 벽돌. 단열·방음 유리, 못 박기 가능, 강도 낮아 비내력용.', '[]'::jsonb, false),
  ('d3efecf5-1351-5c46-b804-3578760b82f1'::uuid, '3장 · 1절 · 조적공사 · 벽돌의종류', '벽돌 규격 · 마름질', '표준형 벽돌 190×90×57mm ※확인. 마름질: 벽돌을 쪼개 반절·이오토막(1/4)·칠오토막(3/4) 등으로 가공하는 일.', '["온장 기준의 토막 명칭이 쌓기법 설명에 계속 등장 — 용어를 먼저 잡을 것."]'::jsonb, true),
  ('da863214-9623-502c-accd-f6c31d7ae506'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '영식쌓기', '한 켜는 마구리, 한 켜는 길이로 번갈아 쌓고, 모서리에 이오토막을 사용.', '["통줄눈이 최소 — 가장 튼튼한 쌓기, 내력벽의 표준."]'::jsonb, false),
  ('ce6b5eef-96f8-5299-88eb-29bfec503976'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '화란식쌓기 (네덜란드식)', '영식과 같으나 모서리에 칠오토막 사용.', '["모서리가 견고하고 시공 쉬움 — 국내에서 가장 많이 쓰는 방식.", "비교·암기 — 영식(이오토막) vs 화란식(칠오토막) — ''모서리 토막''만 다름, 둘 다 마구리·길이 교대."]'::jsonb, false),
  ('75774012-b918-5097-b6f7-6670d03031cd'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '불식쌓기 (프랑스식)', '매 켜에 마구리와 길이가 번갈아 나옴. 외관이 아름다우나 통줄눈이 많아 구조적으로 불리 — 치장용.', '[]'::jsonb, false),
  ('1a2e2719-b34f-5ad0-b80a-50aefc7e3b6d'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '미식쌓기', '앞면 5켜는 길이쌓기, 6켜째 마구리쌓기로 뒷벽과 물림. 표면 치장벽돌+뒷채움 벽돌 구성에 사용.', '["비교·암기 — 강도 순 정리(통상): 영식·화란식(구조) > 미식 > 불식(치장) — ''튼튼한 순서''로 한 줄 암기."]'::jsonb, false),
  ('88685d85-a543-5a82-946c-e6a29b483c93'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '마구리쌓기 · 길이쌓기', '마구리쌓기: 벽면에 벽돌의 짧은 면(마구리)만 보이게. 길이쌓기: 긴 면(길이)만 보이게.', '["마구리쌓기는 두꺼운 벽(1.0B 이상), 길이쌓기는 0.5B 얇은 벽에."]'::jsonb, false),
  ('ed9f19f4-5bcd-54e6-a8ae-3f09669fd54b'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '옆세워쌓기 · 길이세워쌓기', '벽돌을 세워 쌓는 방식 — 옆세워(마구리가 세로로)·길이세워(길이가 세로로). 창대·아치·치장 부위에 사용.', '[]'::jsonb, false),
  ('5761ae62-35e5-58ec-b807-3982b2ef2fdd'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '공간쌓기 (중공벽)', '벽을 두 겹으로 쌓고 사이에 공간(단열재·공기층)을 두는 방식. 단열·방습 목적.', '["두 벽은 벽돌 물림 또는 연결철물(긴결물)로 결속 — 간격·개수 기준 ※확인. 하부에 물빠짐 구멍."]'::jsonb, true),
  ('d2027082-6ca1-52e2-9526-4c3d1affbe42'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '내쌓기', '벽면에서 벽돌을 한 켜씩 내밀어 쌓는 것(선반·처마받이).', '["한 켜당 1/8B, 두 켜당 1/4B씩, 총 내밀기는 2.0B 이하 — 관용 기준 ※확인."]'::jsonb, true),
  ('54a20ea8-a854-5522-a6f1-aa98238bf6d0'::uuid, '3장 · 1절 · 조적공사 · 쌓기법나라별4대방식', '아치쌓기', '개구부 위를 곡선으로 쌓아 상부 하중을 압축력으로 좌우에 전달하는 구조. 부재에 인장이 안 생기게 하는 원리.', '["본아치(주문 제작 쐐기벽돌)·막만든아치·거친아치·층두리아치로 구분."]'::jsonb, false),
  ('0269d87a-0d95-52e9-807c-5878c410523b'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '치장줄눈', '쌓기 후 줄눈 모르타르를 파내고 다시 모양 있게 마감한 줄눈(평·민·볼록·오목·내민줄눈 등).', '["시공: 굳기 전 줄눈 파기(깊이 ※확인) 후 치장줄눈 시공."]'::jsonb, true),
  ('775189e7-ac63-5521-8c68-a489ba23fc12'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '통줄눈 · 막힌줄눈', '통줄눈: 세로줄눈이 상하로 이어짐 — 하중이 한 줄로 집중·균열 취약. 막힌줄눈: 세로줄눈이 엇갈림 — 하중 분산.', '["비교·암기 — ''내력벽은 반드시 막힌줄눈'' — 통줄눈은 보강블록조(속에 철근·콘크리트가 지나가는 경우)에서만 허용되는 논리."]'::jsonb, false),
  ('a4ebff8a-a40a-56a5-98d8-2a10f90f726a'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '하루 쌓기 높이', '벽돌은 하루 1.2m(18켜) 표준, 최대 1.5m(22켜) 이하. ※확인.', '["이유: 굳지 않은 모르타르 위에 과다 하중 — 배부름·붕괴, 균일한 높이로 돌아가며 쌓기."]'::jsonb, true),
  ('e056904d-5cfa-59fa-b2dc-9c2d5af1f4c6'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '테두리보', '조적벽 상부를 철근콘크리트 보로 둘러 벽체를 일체화하는 부재.', '["역할: 벽체 일체성·하중 분산·개구부 상부 보강·지붕(슬래브) 하중 전달 — 조적조 내진의 핵심 부재."]'::jsonb, false),
  ('a8a5167b-c95c-54b9-9be1-1bc40ede109a'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '인방보', '창·문 개구부 바로 위에 걸쳐 상부 벽 하중을 양옆으로 전달하는 보.', '["양단 걸침길이 확보(개구부 폭에 따라 ※확인) — 걸침 부족이 개구부 상부 균열의 단골 원인."]'::jsonb, true),
  ('f2b79cc7-f10c-5d3c-af94-8d3e9267b8c1'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '창대 · 창대돌', '창 밑 벽 상부를 보호하고 빗물을 흘려보내는 부재. 밖으로 물흘림 경사, 벽면보다 내밀어 물끊기.', '[]'::jsonb, false),
  ('59f7605d-b911-515b-8d61-b288365c6b24'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '벽량', '바닥면적당 내력벽 길이(cm/㎡). 조적조·벽식 구조의 내진 안전 지표 — 최소 벽량 규정. ※값 확인.', '[]'::jsonb, true),
  ('5fd6d8b9-d545-5dbc-9b09-231a40737d92'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '부축벽 (버트레스)', '벽에 직각으로 붙여 벽의 횡력(전도)을 지지하는 짧은 벽. 높고 긴 조적벽 보강.', '[]'::jsonb, false),
  ('0320021b-e2f9-55f1-ad7c-e8334fb0fb54'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '신축줄눈 (조적)', '온도·습기 변형을 흡수하도록 벽을 분리해 두는 줄눈. 긴 벽·이질 재료 접합부에 설치.', '[]'::jsonb, false),
  ('15086423-6e94-521f-80a7-c438f21e83a4'::uuid, '3장 · 1절 · 조적공사 · 줄눈과시공규칙', '백화 (조적)', '벽돌·모르타르의 가용 성분이 물에 녹아 표면에서 흰 결정으로 석출되는 현상 — 조적 외벽의 대표 하자.', '["대책: 흡수율 낮은 벽돌, 줄눈 밀실 시공, 물끊기·차수(파라펫 상부 두겁), 발수제 — ''물의 이동을 끊는 것''이 본질."]'::jsonb, false),
  ('275e5304-a6cb-5dbb-925c-1e6c677dec25'::uuid, '3장 · 1절 · 조적공사 · 블록조', '블록조', '속 빈 콘크리트 블록으로 쌓는 구조. 벽돌보다 크고 가벼워 시공 빠름 — 담장·창고·칸막이.', '[]'::jsonb, false),
  ('17378977-414e-5de0-80d1-7866b5ac29ad'::uuid, '3장 · 1절 · 조적공사 · 블록조', '보강블록조', '블록의 빈 속(중공부)에 세로·가로 철근을 넣고 콘크리트(모르타르)로 채워 내력벽으로 만든 구조.', '["이때는 철근이 지나야 하므로 통줄눈으로 쌓음 — 막힌줄눈 원칙의 예외로 출제됨."]'::jsonb, false),
  ('840ce8b4-256b-550c-990b-0a6bddd61e94'::uuid, '3장 · 1절 · 조적공사 · 블록조', 'BI블록 · 중공블록', '기본형(BI)·속빈 블록의 규격 구분. 기본 치수 390×190×(100·150·190). ※확인.', '[]'::jsonb, true),
  ('d03bbea0-7609-5996-9458-49b3fa9f7db6'::uuid, '3장 · 1절 · 조적공사 · 블록조', 'ALC블록', '경량기포콘크리트(고온고압 증기양생) 블록. 가볍고 단열·차음·내화 우수, 톱 절단 가능.', '["흡수율이 커서 물에 약함 — 외벽 사용 시 마감·방수 필수, 전용 모르타르 사용."]'::jsonb, false),
  ('6aaf89a6-b3f4-5d59-a719-63fd126cd5a0'::uuid, '3장 · 1절 · 조적공사 · 블록조', '와이어메시 보강', '수평 줄눈에 격자 철선을 깔아 벽의 균열을 억제하는 보강, 조적 균열 대책의 기본.', '[]'::jsonb, false),
  ('e4d83ef8-d478-568d-be42-c01ce81442f5'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '석재 성인별 분류 (화성·퇴적·변성)', '화성암(마그마 굳음): 화강암·안산암. 퇴적암(퇴적·고결): 사암·석회암. 변성암(열·압력 변성): 대리석·점판암.', '["비교·암기 — ''어떻게 만들어졌나''가 성질을 결정 — 화성암은 단단, 퇴적암은 무름, 변성암은 무늬."]'::jsonb, false),
  ('3263f25a-c050-5cfd-b9a4-7c8685bf4c35'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '화강암', '석영·장석질 화성암. 압축강도·내마모성 최고, 흡수율 낮음 — 외장·바닥의 표준 석재.', '["약점: 내화성 낮음(600도 부근에서 석영 팽창·파괴 ※확인) — ''단단하지만 불에 약하다''가 단골 포인트."]'::jsonb, true),
  ('8ce35162-271b-560d-8307-4d74d6904729'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '안산암', '화산암계 화성암. 강도·내화성 양호, 큰 판재를 얻기 어려움. 구조·조각용.', '[]'::jsonb, false),
  ('53b4cae1-fb23-5e30-94bf-f8c7bb143e16'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '사암', '모래가 고결된 퇴적암. 흡수율 크고 강도 낮음, 가공 쉬움. 내장·치장용.', '[]'::jsonb, false),
  ('4c8f0b67-42e9-5f99-8480-e51814ad039f'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '석회암', '탄산칼슘질 퇴적암. 시멘트의 원료, 산에 약해 외장 부적합.', '[]'::jsonb, false),
  ('ae6a4f62-fdb8-5339-a034-d999b921c44f'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '대리석', '석회암이 변성된 암석. 아름다운 무늬 — 내장 최고급재.', '["산·대기(산성비)에 약하고 내마모성 낮음 — 외장·바닥 사용 부적합이 정답 포인트.", "비교·암기 — 화강암(외장 OK, 불에 약함) ↔ 대리석(내장용, 산에 약함) — 용도·약점 교차 암기."]'::jsonb, false),
  ('36261195-d564-584e-8856-5a725687dff7'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '점판암 (슬레이트)', '이판암이 변성된 얇게 조개지는 암석. 지붕 잇기·바닥재.', '[]'::jsonb, false),
  ('736061cb-2166-569f-a2a2-2bc8627bed0f'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '트래버틴', '다공질 줄무늬의 석회암계 장식석. 특수 내장 치장용.', '[]'::jsonb, false),
  ('c87bda70-2789-5943-9a46-4318773d7e6b'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '테라조', '대리석 종석+시멘트를 다져 굳힌 뒤 갈아낸 인조석. 현장갈기와 공장 제품으로 구분.', '[]'::jsonb, false),
  ('51267269-3f91-54cd-82a7-e1fffab0abfa'::uuid, '3장 · 2절 · 석공사 · 석재의종류성인별', '인조석', '종석+시멘트+안료로 천연석 질감을 모방한 제품. 잔다듬 마감이면 의석이라고도 함.', '[]'::jsonb, false),
  ('4c7495b7-aaa6-5a5a-b869-9f2033dfc24b'::uuid, '3장 · 2절 · 석공사 · 석재표면가공거친순서', '혹두기', '쇠메로 큰 요철만 대강 다듬은 가장 거친 마감.', '["비교·암기 — 가공 순서 암기: 혹두기 - 정다듬 - 도드락다듬 - 잔다듬 - 물갈기. ''혹정도잔물'' 다섯 글자."]'::jsonb, false),
  ('1bf2b0f9-2003-5277-9559-18dfb3c02f0b'::uuid, '3장 · 2절 · 석공사 · 석재표면가공거친순서', '정다듬', '정으로 쪼아 평평하게 다듬는 가공.', '[]'::jsonb, false),
  ('3d246dbf-3fce-5472-9976-ee027215584c'::uuid, '3장 · 2절 · 석공사 · 석재표면가공거친순서', '도드락다듬', '도드락망치(격자날)로 두드려 곱게 다듬는 가공.', '[]'::jsonb, false),
  ('906274b5-3aeb-5929-b5b1-9bcfb2c0de30'::uuid, '3장 · 2절 · 석공사 · 석재표면가공거친순서', '잔다듬', '날망치로 평행선 자국을 내며 곱게 마무리하는 가공.', '[]'::jsonb, false),
  ('f0ab0839-1279-5369-88c3-e434507af63f'::uuid, '3장 · 2절 · 석공사 · 석재표면가공거친순서', '물갈기 (광내기)', '숫돌·연마기로 갈아 광택을 내는 마감(거친갈기-물갈기-본갈기-정갈기).', '[]'::jsonb, false),
  ('ed1fb3d4-3ce4-58c5-8891-47feb70cd018'::uuid, '3장 · 2절 · 석공사 · 석재표면가공거친순서', '버너구이 (화염처리)', '화염으로 표면을 튀겨 거칠게 만드는 마감(제트버너).', '["화강암 전용(석영 팽창 원리 이용). 미끄럼 방지 — 외부 바닥의 표준 마감."]'::jsonb, false),
  ('37279e82-edb7-5e98-bd4a-41f357678b9c'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '습식공법 (석재)', '구조체와 석재 사이에 모르타르를 채워 붙이는 공법.', '["저층·소규모용. 백화 발생, 동해 우려, 모르타르 경화 대기 — 요즘 외벽에선 지양."]'::jsonb, false),
  ('a5cd214d-b708-5874-b323-ac17e53c1f19'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '건식공법 (석재)', '모르타르 없이 앵커·파스너 등 철물로 석재를 구조체에 거는 공법.', '["백화 없음, 동해 없음, 시공 빠름, 층간변위 추종 — 현대 외벽 석공사의 표준.", "비교·암기 — 습식(모르타르 채움) ↔ 건식(철물 걸기) — 백화·공기·변위 추종에서 건식이 우세. 단, 철물 비용과 정밀 시공 요구."]'::jsonb, false),
  ('d3048e6b-6a7c-5405-bf8b-79e5487ba668'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '앵커긴결공법', '건식의 대표 — 구조체에 앵커를 박고 조정판·촉으로 석재를 한 장씩 고정, 판마다 독립 지지되어 하중이 아래 판에 안 쌓임.', '[]'::jsonb, false),
  ('3431d291-dcb5-5cf5-94f7-72cada22661e'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '강재트러스 공법', '미리 짠 강재 틀에 석재를 공장·지상에서 부착 후 유닛으로 설치하는 건식 공법. 고층·대형 벽면의 공기 단축.', '[]'::jsonb, false),
  ('29fdad27-89e3-55c0-9ffa-06ed1ec3fc75'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '파스너 (석재)', '석재를 구조체에 고정하는 연결 철물의 총칭. 스테인리스 등 내식 재질 — 부식되면 석재 탈락 사고.', '[]'::jsonb, false),
  ('079cd0b9-6d82-5e17-bb26-35cfcd68d907'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '촉 · 연결철물', '석재 상하·좌우 판을 맞물리는 핀(촉)과 긴결 철물. 지진·풍압 시 탈락 방지.', '[]'::jsonb, false),
  ('9e5c3a4d-e2a0-57d1-b883-b7a48ee43123'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '오픈조인트', '석재 판 사이 줄눈을 실링으로 막지 않고 열어 두되, 내부에 등압 공간+2차 방수층을 두어 물을 처리하는 방식.', '["원리: 줄눈 안팎 압력차를 없애면(등압) 물이 빨려 들어가지 않는다 — 커튼월 등압이론과 동일한 사고."]'::jsonb, false),
  ('da122e18-8ece-5316-9d88-391464771afa'::uuid, '3장 · 2절 · 석공사 · 석재붙임공법', '석재 실링', '줄눈을 실런트로 충전하는 마감. 오염(실런트 성분 이행에 의한 석재 얼룩) 방지용 논스테인 실런트 사용.', '[]'::jsonb, false),
  ('0ce8cd19-d8b3-5efd-a3ad-13d1ae060606'::uuid, '3장 · 3절 · 창호유리공사 · 창호재질과구성', '목재창호', '단열·질감 우수, 변형·내구·방화 약점 — 내부용 중심.', '[]'::jsonb, false),
  ('a4361755-7451-597d-82d8-01a7dfae9713'::uuid, '3장 · 3절 · 창호유리공사 · 창호재질과구성', '강재창호', '강판 절곡·용접 창호. 견고·방화문 재료, 무겁고 녹 관리 필요.', '[]'::jsonb, false),
  ('f0def721-4ff1-5966-a208-82f3100f4019'::uuid, '3장 · 3절 · 창호유리공사 · 창호재질과구성', '알루미늄창호', '압출 성형 새시. 가볍고 정밀·내식 — 현대 창호의 주류.', '["약점: 열전도 큼(결로) — 단열바(폴리아미드 열교차단재) 삽입으로 해결. 알칼리(모르타르)에 부식 주의."]'::jsonb, false),
  ('e54363f4-f3fc-5d73-aef1-6223abcbd689'::uuid, '3장 · 3절 · 창호유리공사 · 창호재질과구성', '합성수지(PVC)창호', 'PVC 압출 창호(하이새시). 단열·기밀 우수·경제적 — 주거 표준.', '["비교·암기 — 알루미늄(강성·대형 개구 유리, 열에 불리) ↔ PVC(단열 유리, 강성 낮아 대형 취약) — 용도로 갈림."]'::jsonb, false),
  ('260ea32f-464c-5f43-80ea-e4cae4acda71'::uuid, '3장 · 3절 · 창호유리공사 · 창호재질과구성', '새시 · 프레임', '유리를 끼우는 창틀 부재(새시)와 창호 전체 틀(프레임).', '[]'::jsonb, false),
  ('40c4953e-a5dd-5820-8b3c-f43c14a5b5bd'::uuid, '3장 · 3절 · 창호유리공사 · 창호재질과구성', '멀리언 · 트랜섬', '멀리언: 수직 구획 부재(선틀). 트랜섬: 수평 구획 부재.', '["커튼월에서도 동일 용어 사용 — 수직=멀리언, 수평=트랜섬."]'::jsonb, false),
  ('caadfd16-d8ab-5282-a05f-01db4a208c4b'::uuid, '3장 · 3절 · 창호유리공사 · 창호의형식', '여닫이 · 미닫이 · 미서기', '여닫이: 경첩 회전 개폐(기밀 유리). 미닫이: 옆으로 밀어 벽 속·벽면으로 숨김. 미서기: 두 짝이 겹치며 미끄러짐(주거 창의 표준).', '["비교·암기 — 미닫이(한 장이 사라짐) vs 미서기(두 장이 겹침) — 헷갈리기 쉬운 짝."]'::jsonb, false),
  ('ee8ad47b-33dc-5ce4-8f3e-d9b8e0df9656'::uuid, '3장 · 3절 · 창호유리공사 · 창호의형식', '오르내리창', '상하 두 짝을 위아래로 미는 창. 개폐 균형추·기밀 확보.', '[]'::jsonb, false),
  ('d768ae3f-8895-5ab4-a93b-633f0f777d9b'::uuid, '3장 · 3절 · 창호유리공사 · 창호의형식', '회전문 · 자동문', '회전문: 출입 시 외기 차단(방풍) 우수 — 고층 로비. 자동문: 센서 개폐 — 끼임 방지 안전장치 필수.', '[]'::jsonb, false),
  ('195c02ac-525f-51e6-bda6-d9704d1a4eb7'::uuid, '3장 · 3절 · 창호유리공사 · 창호철물', '경첩 (힌지)', '여닫이 회전축 철물.', '[]'::jsonb, false),
  ('d506f1b2-9aba-58d0-aa3d-3aab3fb8d49b'::uuid, '3장 · 3절 · 창호유리공사 · 창호철물', '피봇힌지', '문 상하 축으로 회전시키는 지도리 철물. 중량문·현관문에 사용.', '[]'::jsonb, false),
  ('cae30277-17af-59cf-9270-403a92fc3211'::uuid, '3장 · 3절 · 창호유리공사 · 창호철물', '플로어힌지', '바닥에 매입된 유압 장치로 문을 자동으로 닫는 축 철물. 중량 강화유리문·현관문의 표준.', '["비교·암기 — 도어체크(문 위에 달림) ↔ 플로어힌지(바닥에 묻힘) — 위치로 구분, 역할(자동 닫힘)은 유사."]'::jsonb, false),
  ('99d8ccc3-2bfa-5df1-acd0-0535e5a82fd7'::uuid, '3장 · 3절 · 창호유리공사 · 창호철물', '도어체크 (도어클로저)', '문 상부에 달아 열린 문을 서서히 자동으로 닫는 장치. 방화문에 필수(항상 닫힘 유지).', '[]'::jsonb, false),
  ('9dceffc7-0932-527a-866b-39d9c7e32e89'::uuid, '3장 · 3절 · 창호유리공사 · 창호철물', '도어스톱', '문이 벽에 부딪히지 않게 멈추는 철물.', '[]'::jsonb, false),
  ('ad890cee-a72a-5036-9ce9-7716e1e911ed'::uuid, '3장 · 3절 · 창호유리공사 · 창호철물', '크레센트', '미서기창의 잠금 철물(초승달 모양). 기밀을 당겨 조이는 역할 겸함.', '[]'::jsonb, false),
  ('86bd5b1c-63e8-5a03-89cc-00f01ff3c44d'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '판유리 (플로트유리)', '용융 주석 위에 띄워 만든 평활 판유리. 모든 가공 유리의 원판.', '[]'::jsonb, false),
  ('22e87321-6eed-584b-b671-af0487f8f668'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '강화유리', '판유리를 연화점 부근까지 가열 후 급랭해 표면에 압축응력을 준 유리. 강도 3~5배, 파손 시 팥알 조각(안전).', '["가공(절단·구멍) 후 강화해야 함 — 강화 후 절단 불가. 자파 현상(황화니켈) 주의 — 대책: 히트소크 시험."]'::jsonb, false),
  ('4cf8abd1-fc28-55c7-97cb-2892618a3f76'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '배강도유리', '강화보다 완만히 냉각한 반강화 유리. 강도 2배, 파손 시 큰 조각으로 판에 붙어 낙하 위험 적음 — 고층 외벽용.', '["비교·암기 — 강화(강하지만 통째로 와르르, 자파 우려) ↔ 배강도(덜 강하지만 깨져도 판에 붙어 있음) — 고층 외장에 배강도를 쓰는 이유."]'::jsonb, false),
  ('15a44171-d1f7-546e-98b4-09fca01e8453'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '접합유리', '두 장 이상 유리 사이에 접합필름(PVB)을 넣어 붙인 유리. 깨져도 필름에 붙어 관통·비산 방지.', '["방범·천창·난간 등 안전 요구 부위의 표준."]'::jsonb, false),
  ('f359e42d-e703-57e0-87bb-2d12f5a644af'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '망입유리', '철망을 넣은 유리. 파손 시 비산 방지·방화용. 단, 망 부식에 의한 테두리 녹 터짐 주의.', '[]'::jsonb, false),
  ('b0bff7b5-9cfa-5e29-8b54-d33a8adab294'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '복층유리 (페어글라스)', '유리 두 장 사이에 건조 공기층(간봉+흡습제)을 밀봉한 유리. 단열·결로 방지의 기본.', '["공기층 두께·아르곤 충전·로이 코팅 조합으로 성능 상승."]'::jsonb, false),
  ('3821e381-11dd-518a-909a-649c15d5daf2'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '로이유리 (Low-E)', '표면에 금속 박막을 코팅해 방사율을 낮춘 유리 — 복사열을 반사해 겨울엔 난방열을 안으로, 여름엔 일사를 밖으로.', '["복층 구성 시 코팅면 위치로 성능이 갈림 ※확인. 현행 에너지 기준의 사실상 표준."]'::jsonb, true),
  ('3253a217-997b-545b-adfe-7a68c5ab59a0'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '진공유리', '두 유리 사이를 진공으로 만들어 대류·전도를 차단한 초단열 유리. 얇은 두께로 고성능.', '[]'::jsonb, false),
  ('42a7e8d5-0f23-5faa-bf98-d891ae4d8b1a'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '열선반사유리', '표면 금속 코팅으로 일사를 거울처럼 반사. 냉방부하 저감·프라이버시 — 주변 눈부심(빛 공해) 민원 유의.', '[]'::jsonb, false),
  ('be9bfd8c-5373-54f5-8859-35cad9b69175'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '열선흡수유리', '성분 착색으로 일사를 흡수하는 색유리. 흡수열로 유리 온도가 올라 열파손 주의.', '[]'::jsonb, false),
  ('5aa67464-3f8e-56c2-be35-bc19494ea679'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '유리블록', '속이 빈 유리 벽돌. 채광+단열+차음 칸막이.', '[]'::jsonb, false),
  ('e1cd80d6-2350-541b-9687-acdc04c0d176'::uuid, '3장 · 3절 · 창호유리공사 · 유리의종류', '스팬드럴유리', '층간 슬래브·설비 구간을 가리는 불투명(세라믹 도장) 유리. 커튼월 외관 통일용.', '[]'::jsonb, false),
  ('bdf19384-7804-5472-8d71-a506571f75b9'::uuid, '3장 · 3절 · 창호유리공사 · 유리끼우기와파손', '그레이징', '유리를 새시에 고정하는 작업 총칭. 퍼티·가스켓·실런트·구조용 실런트(SSG) 방식.', '[]'::jsonb, false),
  ('94640895-3975-5059-9066-85859f5cc405'::uuid, '3장 · 3절 · 창호유리공사 · 유리끼우기와파손', '퍼티 · 가스켓 · 실런트 (유리)', '고정 재료 3종 — 퍼티(반죽, 재래), 가스켓(고무 압착, 건식), 실런트(습식 충전).', '[]'::jsonb, false),
  ('5ace07d2-f166-5369-b78d-7f96c503ef2d'::uuid, '3장 · 3절 · 창호유리공사 · 유리끼우기와파손', 'SSG · DPG 공법', 'SSG(Structural Sealant Glazing): 구조용 실런트로 유리를 프레임에 접착 — 외부에서 프레임이 안 보임. DPG(Dot Point Glazing): 유리에 구멍을 내 볼트(로틀)로 지지 — 프레임 없는 대형 유리벽.', '["둘 다 실런트·볼트가 구조 부재 — 접합 품질·검사가 안전과 직결."]'::jsonb, false),
  ('806595bb-a77a-56ea-a581-af1d6457fb41'::uuid, '3장 · 3절 · 창호유리공사 · 유리끼우기와파손', '백업재 · 세팅블록', '백업재: 실런트 줄눈 깊이를 조절하는 채움재. 세팅블록: 유리 자중을 새시에 전달하도록 밑에 받치는 블록(양 끝 1/4 지점 ※확인).', '[]'::jsonb, true),
  ('c9585e8e-1ef6-5abd-8eb5-686fc1183eb8'::uuid, '3장 · 3절 · 창호유리공사 · 유리끼우기와파손', '유리의 열파손', '유리 중앙(일사 가열)과 가장자리(프레임에 가려 저온)의 온도차 응력으로 깨지는 현상.', '["열선흡수유리·배면 차양·필름 부착 시 위험 증가. 대책: 단부 절단면 품질, 강화·배강도 사용, 커튼·차양 이격."]'::jsonb, false),
  ('e7a800a0-cae4-5ade-944d-0abcbaa7643a'::uuid, '3장 · 3절 · 창호유리공사 · 유리끼우기와파손', '단열간봉 (단열바)', '복층유리 가장자리 간봉을 열전도 낮은 재질로 바꾼 것. 유리 가장자리 결로 억제(웜엣지).', '[]'::jsonb, false),
  ('a59b33a9-1df2-5a23-a843-2cbb9709ea81'::uuid, '3장 · 4절 · 커튼월', '커튼월', '구조체 밖에 매달아 대는 비내력 외벽(커튼처럼 걸림). 자중과 풍하중만 부담 — 초고층 외벽의 표준.', '["재질: 금속(알루미늄)+유리, 석재, PC 패널. 요구 성능: 풍압·기밀·수밀·층간변위 추종·단열·내화(층간구획)."]'::jsonb, false),
  ('d296fc18-3bbf-5b9e-84b1-95879c77328d'::uuid, '3장 · 4절 · 커튼월 · 방식분류', '유닛월 방식', '공장에서 프레임+유리+패널을 유닛으로 완성해 현장에서 걸기만 하는 방식.', '["품질 균일·현장 공기 단축·고소 작업 감소 — 초고층 표준, 운반·양중 계획이 관건."]'::jsonb, false),
  ('b017ae53-4cda-5eb3-b2c1-504e7695f4f7'::uuid, '3장 · 4절 · 커튼월 · 방식분류', '스틱월 방식', '멀리언·트랜섬 부재를 현장에서 조립하고 유리를 끼우는 방식.', '["융통성 있고 운반 유리, 현장 품질 관리 부담 — 중저층·복잡 형상.", "비교·암기 — 유닛(공장 조립·고층) ↔ 스틱(현장 조립·중저층) — PC vs 현장타설의 관계와 같은 구도."]'::jsonb, false),
  ('c9e76a14-b757-578d-98fd-91c7405b37e2'::uuid, '3장 · 4절 · 커튼월 · 방식분류', '패널 방식', '콘크리트(PC)·금속 패널을 통째로 거는 방식. 창은 패널에 선부착 또는 별도.', '[]'::jsonb, false),
  ('d9ba478f-bfd9-51b2-ae41-6d0bb757fd2a'::uuid, '3장 · 4절 · 커튼월 · 고정과변위추종', '파스너 (고정·회전·슬라이드)', '커튼월을 구조체(슬래브 단부)에 고정하는 철물. 고정형+가동형(회전·슬라이드)을 조합해 층간변위·열변형을 흡수.', '["''단단히 붙이기만 하면 지진 때 유리가 깨진다'' — 움직임을 허용하는 설계가 핵심 논리."]'::jsonb, false),
  ('38ea2bb9-7063-501f-9a98-f5f270e10870'::uuid, '3장 · 4절 · 커튼월 · 고정과변위추종', '층간방화구획 (커튼월)', '커튼월과 슬래브 사이 틈을 내화재(암면 등)로 막아 층간 화재 확산을 차단하는 조치.', '["커튼월 화재 수직 확산 사고의 핵심 쟁점 — 틈새 밀실 시공 여부가 관건."]'::jsonb, false),
  ('5e9d30a0-4454-5980-b121-adec8e79abae'::uuid, '3장 · 4절 · 커튼월 · 성능시험', '커튼월 성능시험', '실물 모형(목업)으로 설계 성능을 사전 검증하는 시험 일체. 예압-기밀-정압수밀-동압수밀-구조-층간변위 순서로 수행. ※순서·조건 확인.', '[]'::jsonb, true),
  ('a7ab5f4a-cf65-5f52-b16a-7222c2c78aeb'::uuid, '3장 · 4절 · 커튼월 · 성능시험', '풍동시험', '건물 축소 모형으로 설계 풍압(부위별 피크 외압)을 구하는 시험. 커튼월 구조 설계의 입력값.', '[]'::jsonb, false),
  ('b7d68b12-cf94-5f2f-9f03-4dad0a3d8b2c'::uuid, '3장 · 4절 · 커튼월 · 성능시험', '기밀시험', '압력차를 주어 공기 누출량을 측정. 에너지·소음 성능의 기초.', '[]'::jsonb, false),
  ('41b3e76a-2133-5d43-8f3a-a8418cacbcb6'::uuid, '3장 · 4절 · 커튼월 · 성능시험', '수밀시험', '정압(일정 압력)·동압(맥동 압력)+살수로 누수 여부를 확인.', '["실제 폭풍우(바람+비)를 재현하는 것이 동압수밀 — 정압만 통과해선 부족하다는 논리."]'::jsonb, false),
  ('862713f5-e30f-51b6-b1d5-98d24c64cfac'::uuid, '3장 · 4절 · 커튼월 · 성능시험', '구조시험 · 층간변위시험', '설계 풍압의 배수 하중에서 변형·파손 확인(구조), 좌우 강제 변위로 유리 파손·탈락 확인(층간변위).', '[]'::jsonb, false),
  ('89d87778-bb50-5e1a-8d2a-e71808495b09'::uuid, '3장 · 4절 · 커튼월 · 성능시험', '필드테스트 (현장살수)', '설치 후 현장에서 살수해 시공 품질(누수)을 확인하는 시험. 목업 합격과 별개로 현장 품질을 잡는 절차.', '[]'::jsonb, false),
  ('a91c9d43-b476-50a1-83b4-0ea6271146cd'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '멤브레인방수', '구조체 표면에 연속된 방수막(멤브레인)을 형성하는 방수의 총칭 — 아스팔트·시트·도막이 3대 계열.', '["비교·암기 — 이 절 전체의 지도: 막 방수(아스팔트/시트/도막) + 시멘트계(액체·침투) + 특수(벤토나이트·금속) + 줄눈(실링)."]'::jsonb, false),
  ('bf12dc2a-7650-52c8-b788-ac1289c7f882'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '아스팔트방수 (열공법)', '가열 용융 아스팔트로 펠트·루핑을 여러 겹 적층하는 전통 방수(8층 구성 등).', '["신뢰성 높고 수명 김, 화기 사용·냄새·중량, 숙련 의존 — 옥상 누름 방수의 고전."]'::jsonb, false),
  ('8cbfc885-67ff-59d6-81e4-bf88d721158a'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '아스팔트프라이머', '아스팔트를 용제에 녹인 초벌 도포재. 바탕과 방수층의 접착을 만드는 첫 층.', '["''방수의 첫 공정은 바탕 처리+프라이머'' — 순서 문제 단골."]'::jsonb, false),
  ('e198e5f5-a775-58b6-bf77-cc1c32995c8d'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '아스팔트펠트', '유기 섬유 원지에 아스팔트를 침투시킨 시트(침투만).', '[]'::jsonb, false),
  ('4caea256-f052-5609-b664-d1db818b90bc'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '아스팔트루핑', '펠트에 아스팔트를 다시 피복하고 광물질 가루를 입힌 시트(침투+피복).', '["비교·암기 — 펠트(침투만·안쪽 층) ↔ 루핑(피복까지·바깥 층) — 층 구성에서의 위치로 기억."]'::jsonb, false),
  ('16b250e9-eafe-59b0-b8e1-b3c19cab5fb3'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '스트레이트아스팔트', '증류 그대로의 아스팔트. 신율·침투성 크지만 연화점 낮음(더위에 흘러내림) — 지하실 등 온도 변화가 적은 곳.', '[]'::jsonb, false),
  ('2755ec45-ca1e-5f10-a4be-8aee1bed8715'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '블론아스팔트', '공기를 불어넣어 산화시킨 아스팔트. 연화점 높고 온도 안정 — 옥상 방수용.', '["비교·암기 — 스트레이트(잘 스며들고 잘 늘어남, 더위 약함) ↔ 블론(온도에 강함, 신율 작음) — 옥상은 블론."]'::jsonb, false),
  ('331a00b0-869d-5029-baa1-55673e76c31d'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '아스팔트컴파운드', '블론에 광물분·섬유·유지를 섞어 성능(신율·접착)을 개량한 최상급 방수 아스팔트.', '[]'::jsonb, false),
  ('277ebf46-35f8-5c64-a76c-02ee9882516c'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '침입도', '25도에서 표준 침이 아스팔트에 관입한 깊이(0.1mm 단위). 굳기의 지표 — 클수록 무름.', '["침입도(굳기)와 연화점(내열)이 아스팔트 품질의 양대 지표."]'::jsonb, false),
  ('04d1fb0b-98ea-5779-be7a-8200ea16cbac'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '연화점', '아스팔트가 물러지기 시작하는 온도. 옥상용은 연화점이 높아야 함.', '[]'::jsonb, false),
  ('0857ab18-299f-51a4-acb7-6461a60ea572'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '개량아스팔트시트방수 (토치)', '고무·수지로 개량한 아스팔트 시트를 토치로 뒷면을 녹여 붙이는 방수. 가마솥 없이 시트 한두 겹으로 — 현재 아스팔트계 주류.', '["겹침부 용융 접착 품질이 생명. 화기 사용 — 화재 예방 조치 필수."]'::jsonb, false),
  ('3945134d-1fae-5162-9db3-777b1b22b713'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '합성고분자시트방수', '합성고무(EPDM)·PVC 등 시트를 접착제·고정철물로 붙이는 방수. 1겹 시공·경량·신율 큼.', '["약점은 이음부(조인트) — 겹침 접합 품질과 바람 들뜸 관리."]'::jsonb, false),
  ('6c604f30-eeef-528c-a2e0-f5004e347037'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '자착식시트방수', '뒷면에 점착층이 있어 화기 없이 눌러 붙이는 시트. 화재 위험 없는 개보수·실내에 확대.', '[]'::jsonb, false),
  ('59fa573f-cd71-5414-b14e-34187b61ef51'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '도막방수', '액상 방수재를 발라 이음매 없는(심리스) 도막을 형성하는 방수.', '["장점: 복잡 형상·수직면 유리, 이음매 없음. 약점: 두께 균일 확보(핀홀) — 두께 관리가 품질의 전부."]'::jsonb, false),
  ('fe0519a0-560e-5f66-84de-0ee2b56cfc28'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '우레탄도막방수', '우레탄 수지 도막. 탄성·신율 우수, 노출 옥상·베란다의 표준. 자외선 보호 톱코트 필요.', '[]'::jsonb, false),
  ('a98739cc-5bd8-592f-a21e-87b55e0256b1'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', 'FRP도막방수', '유리섬유 매트+수지 적층. 강도·내마모 최고 — 주차장 램프·욕조, 신율 작아 거동 큰 바탕엔 불리.', '[]'::jsonb, false),
  ('9c8e0673-26a5-5e0b-86d8-49c207e6cef9'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '고무아스팔트도막방수', '고무화 아스팔트 에멀션을 도포·뿜칠. 비노출(보호층 필요) 지하 외벽 등에 사용.', '[]'::jsonb, false),
  ('ef9f0c66-d6b6-5f6a-b36a-e1c17e081740'::uuid, '3장 · 5절 · 방수공사 · 멤브레인방수', '복합방수', '시트+도막 등 이종 재료를 겹쳐 서로의 약점(이음부·핀홀)을 보완하는 방수. 최근 표준화 추세.', '[]'::jsonb, false),
  ('9de491f5-b800-5b2c-bac9-b0b301ffbe33'::uuid, '3장 · 5절 · 방수공사 · 시멘트계기타방수', '시멘트액체방수', '방수제를 섞은 시멘트 페이스트·모르타르를 여러 층 발라 방수층을 만드는 공법.', '["저렴·간편, 바탕 균열에 그대로 깨짐(신율 없음) — 지하실·수조 등 거동 작은 실내부용, 신뢰도는 멤브레인보다 낮음."]'::jsonb, false),
  ('b7834d50-a16c-5b9e-b0fb-8632dad6f400'::uuid, '3장 · 5절 · 방수공사 · 시멘트계기타방수', '폴리머시멘트방수', '시멘트에 폴리머(수지)를 혼입해 신율·접착을 개선한 도막형 방수, 액체방수의 개량형.', '[]'::jsonb, false),
  ('f0e09178-299d-5c14-b1d0-877b4d77504d'::uuid, '3장 · 5절 · 방수공사 · 시멘트계기타방수', '침투성방수', '규산질계 재료가 콘크리트 공극에 침투·결정을 생성해 조직 자체를 치밀화하는 방수. 배면수(음압) 대응 가능 — 지하 구방수.', '[]'::jsonb, false),
  ('dc9494bf-d07a-5d22-b8f6-f38ee27a01d2'::uuid, '3장 · 5절 · 방수공사 · 시멘트계기타방수', '벤토나이트방수', '물과 만나면 크게 팽윤하는 벤토나이트 점토 시트로 지하 외벽·바닥을 감싸는 방수.', '["''스스로 부풀어 물길을 막는'' 자가치유형 — 시공 중 우수 관리(미리 젖으면 팽윤 소모) 주의."]'::jsonb, false),
  ('db5ea30b-2859-50ac-8bcc-a69ea61fc57d'::uuid, '3장 · 5절 · 방수공사 · 시멘트계기타방수', '금속판방수', '스테인리스·동판 등을 용접해 잇는 방수. 반영구적 — 특수 부위(수조·문화재).', '[]'::jsonb, false),
  ('ea28d3ed-0577-5912-a8be-0e7561dc5870'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '실링방수', '부재 이음 줄눈을 탄성 실링재로 충전하는 방수. 커튼월·창호 주위·패널 줄눈 — 외벽 누수의 최전선.', '[]'::jsonb, false),
  ('3a75b204-b262-5926-b861-cd081a2a9779'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '실런트', '탄성 충전재(실리콘·변성실리콘·우레탄·아크릴계). 부위·피착재에 따라 선정(유리=실리콘, 도장부=변성실리콘·우레탄 등).', '[]'::jsonb, false),
  ('8085a7c5-b267-5a4c-8557-af5af2f47356'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '코킹', '실링 작업의 통칭(전통적으로는 유성 코킹재). 현장에서는 실링과 혼용.', '[]'::jsonb, false),
  ('28b997f3-cae4-58e4-a06b-386f86aac7cf'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '백업재 (실링)', '줄눈 깊이를 조절하고 3면접착을 막기 위해 밑에 채우는 발포재.', '[]'::jsonb, false),
  ('13f62c50-d1f4-5cc6-bbde-16aaf7b09b1a'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '본드브레이커', '줄눈이 얕아 백업재를 못 넣을 때 바닥면 접착을 끊는 테이프.', '[]'::jsonb, false),
  ('372c9c7e-20d5-517e-93d8-078f0d698573'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '2면접착 · 3면접착', '실런트가 줄눈 양 옆 2면에만 붙어야(2면접착) 늘었다 줄었다 자유롭게 거동함, 바닥까지 붙으면(3면접착) 움직일 때 찢어짐.', '["비교·암기 — ''움직이는 줄눈은 반드시 2면접착'' — 백업재·본드브레이커의 존재 이유. 방수 면접 단골 원리."]'::jsonb, false),
  ('7a80627e-3161-5c1b-9dc4-0aaf86384161'::uuid, '3장 · 5절 · 방수공사 · 실링방수줄눈의방수', '워킹조인트 · 논워킹조인트', '워킹조인트: 온도·바람으로 계속 움직이는 줄눈(커튼월 등) — 2면접착+저모듈러스 실런트. 논워킹조인트: 거의 움직이지 않는 줄눈(콘크리트 이음 등) — 3면접착 허용.', '[]'::jsonb, false),
  ('88ad311f-56f6-551c-a62d-24a51b2d99c4'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '외방수 · 내방수', '외방수: 지하 외벽의 바깥(물이 오는 쪽)에 방수 — 구조체까지 보호, 원칙적 정답, 보수 곤란. 내방수: 안쪽에 방수 — 시공·보수 쉬움, 수압에 밀리고 구조체가 젖음.', '["비교·암기 — ''방수는 물 오는 쪽에 하는 것이 원칙'' — 외방수 우선, 내방수는 보수·차선."]'::jsonb, false),
  ('4f8aac60-face-5c69-838c-6ddcb7283bda'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '방수턱', '출입구·설비 기초 둘레에 콘크리트 턱을 두어 물의 월류를 막는 상세. 방수층 끝단을 올려붙이는 자리.', '[]'::jsonb, false),
  ('733881fd-5fb2-51e6-9b53-121d5f7df201'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '물끊기', '창대·파라펫 밑면에 홈·돌출을 두어 빗물이 벽면을 타고 돌아 들어오지 못하게 끊는 상세.', '["작은 홈 하나가 오염·누수를 좌우 — ''물은 표면장력으로 밑면을 타고 온다''는 원리로 설명."]'::jsonb, false),
  ('b5901b4a-db8e-5058-8e44-eeb6fcdb7b32'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '후레싱 (플래싱)', '파라펫 상부·창호 주위 등 취약부를 덮는 금속판 물처리 부재(두겁 포함).', '[]'::jsonb, false),
  ('a8f5f171-5321-51d8-98d0-525d0f835e1c'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '파라펫', '옥상 둘레의 낮은 난간벽, 방수층 치켜올림(수직 연장) 높이 확보 — 관용 250~300mm 이상 ※확인.', '["파라펫 상부(두겁)·모서리가 드레인·관통부와 함께 방수 3대 취약부."]'::jsonb, true),
  ('c11fee18-717d-5040-b531-a1d4ea11adc0'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '신축줄눈 (방수)', '누름 콘크리트에 일정 간격으로 두는 줄눈. 누름층의 온도 수축 균열이 방수층을 찢지 않게 분리.', '[]'::jsonb, false),
  ('9b43d7f1-f036-5ae2-a130-38212e30a29e'::uuid, '3장 · 5절 · 방수공사 · 방수상세물을다루는디테일', '담수시험', '방수 완료 후 물을 채워 일정 기간(48시간 등 ※확인) 누수를 확인하는 시험, 보호층 시공 전 필수.', '[]'::jsonb, true),
  ('bc4356c2-14c5-517c-a38a-3ec2d7fedb96'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕의형태와물매', '지붕물매 (경사)', '지붕 경사도(수평 10에 대한 수직 치수 등으로 표기).', '["물매 결정 요인: 지붕 재료(재료 조각이 클수록 완만 가능), 강우량, 간사이, 재료별 최소 물매 규정 ※확인."]'::jsonb, true),
  ('2837a9d3-8e35-5b36-9758-a058f2ce01da'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕의형태와물매', '평지붕', '물매가 거의 없는 지붕(옥상). 방수가 성능의 전부 — 멤브레인 방수+누름층 구성.', '[]'::jsonb, false),
  ('60d7f61f-623c-55dc-85f7-50e5c80aab00'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕의형태와물매', '박공지붕', '책을 엎어 놓은 양면 경사 지붕. 가장 단순·보편적.', '[]'::jsonb, false),
  ('36099ccb-1066-5ba7-bf0e-c18a47d4e0be'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕의형태와물매', '모임지붕', '네 면이 모두 경사진 지붕(우진각). 처마가 사방을 보호.', '[]'::jsonb, false),
  ('c58fd415-c6e4-5a2f-a19a-c1dc820d8c9b'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕의형태와물매', '외쪽지붕', '한 방향만 경사진 지붕.', '[]'::jsonb, false),
  ('fb8a6c97-ab58-5694-bd97-51c6ee70e215'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕의형태와물매', '톱날지붕', '톱니 모양 반복 지붕. 수직면 채광창을 북향으로 — 균일 채광의 공장 지붕.', '[]'::jsonb, false),
  ('a576ef68-8dec-5347-8590-4a4bf2ba3046'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕잇기재료', '점토기와', '점토 소성 기와. 전통·내구 우수, 무거움(지붕 구조 부담).', '[]'::jsonb, false),
  ('fee2352e-26d3-5f7b-ad29-dc2aab265353'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕잇기재료', '금속기와', '강판 성형+돌입힘 기와. 경량·시공 빠름 — 점토기와 대체재.', '[]'::jsonb, false),
  ('a39644d5-127b-50ad-8d90-b1bb9d1afa72'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕잇기재료', '아스팔트싱글', '유리섬유 기재+아스팔트+돌입힘의 유연한 지붕 잇기재. 경량·경제적·곡면 대응 — 경사지붕의 대중적 마감.', '["바람 들뜸(태풍) 취약 — 접착·못 고정 관리."]'::jsonb, false),
  ('d6b7e21c-da8f-5c46-9279-320b2957f6f6'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕잇기재료', '금속지붕 (거멀접기·돌출이음)', '금속판을 접어 잇는 지붕. 거멀접기: 판 가장자리를 서로 말아 접는 이음 — 못 구멍 없는 연속 방수.', '["경량·장스팬·낮은 물매 가능 — 대형 지붕의 표준. 열신축(온도 변형) 처리와 바람 들뜸이 설계 포인트."]'::jsonb, false),
  ('2a554df1-6142-5990-bffd-b09e2ea8d0bb'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕각부명칭', '처마 · 박공', '처마: 외벽 밖으로 내민 지붕 끝(벽 보호). 박공: 경사 지붕 옆면의 삼각형 벽 부분.', '[]'::jsonb, false),
  ('5155997a-b41a-5d4f-97ce-228439077e8a'::uuid, '3장 · 6절 · 지붕홈통공사 · 지붕각부명칭', '용마루 · 추녀 · 골', '용마루: 지붕 최상부 수평 마루. 추녀: 모서리로 내려가는 경사 마루(외측 능선). 골(밸리): 두 지붕면이 만나 물이 모이는 오목한 선.', '["골은 물이 집중되는 곳 — 지붕 누수의 최대 취약부(골 후레싱 필수)."]'::jsonb, false),
  ('9b129f60-2080-5c79-8b7d-8cdb3070b595'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '처마홈통', '처마 끝에 수평으로 달아 빗물을 받는 홈통. 경사(물매)를 두어 깔때기로 유도.', '[]'::jsonb, false),
  ('b5dae3cd-c62a-51e9-a3bf-761008315f51'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '선홈통', '빗물을 수직으로 내리는 관. 하부는 낙수받이·배수관 접속.', '[]'::jsonb, false),
  ('7470e1f0-5275-58c7-bf48-90e7ae3a7a3d'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '깔때기홈통', '처마홈통과 선홈통을 잇는 깔때기 모양 부분.', '["비교·암기 — 빗물의 여정으로 암기: 지붕면 - 골 - 처마홈통 - 깔때기홈통 - 선홈통 - 낙수받이 - 배수."]'::jsonb, false),
  ('c6d85306-8b0a-5e1a-878a-df5f348432e0'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '낙수받이', '선홈통 하부에서 물을 받아 튀김 없이 배수로로 보내는 받이.', '[]'::jsonb, false),
  ('4f1f4888-f1e4-538d-a1ee-e0bf139e722b'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '루프드레인', '평지붕·발코니의 바닥 배수구(재등장). 이물질 거름망+방수층 접속 상세가 핵심.', '[]'::jsonb, false),
  ('e06ee2ca-d160-5e5c-a0e5-cd50f7c466ac'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '무근콘크리트 누름층', '옥상 방수층 위에 타설해 방수층을 보호하고 눌러 주는 층(보호 누름).', '["와이어메시 보강+신축줄눈 세트 — 누름층 균열이 방수층을 찢지 않게 하는 구성."]'::jsonb, false),
  ('feffd564-ac96-535d-ae86-4249b09c99fa'::uuid, '3장 · 6절 · 지붕홈통공사 · 홈통빗물의길', '지붕 단열 · 배수 구배', '옥상 단열 위치(방수층 위=역전지붕 / 아래=일반)와 물이 고이지 않는 구배(1/100~1/50 관용 ※확인) 확보.', '["역전지붕: 단열재가 방수층을 자외선·온도에서 보호 — 방수 수명 연장 논리."]'::jsonb, true),
  ('ed62bb81-88a3-5e17-ab3c-f5450e0cd89d'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재유기질', '단열재', '열전도율이 낮은 재료로 열 이동을 줄이는 재료 총칭. 유기질(발포 플라스틱: 싸고 성능 좋음, 불에 약함)과 무기질(광물 섬유: 불연, 성능·시공성 열세)의 대립 구도가 이 절의 핵심.', '[]'::jsonb, false),
  ('225eac6c-da93-5011-b328-45c3f4855bef'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재유기질', '비드법보온판 (EPS)', '발포 폴리스티렌 알갱이를 융착한 판(스티로폼). 저렴·가공 쉬움. 1종(흰색)·2종(흑연 첨가, 성능 개선).', '[]'::jsonb, false),
  ('316de345-f1c9-58d8-9b40-e395241952ed'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재유기질', '압출법보온판 (XPS)', '폴리스티렌을 압출 발포한 판(아이소핑크). 독립 기포로 흡수율 낮음 — 땅에 닿는 부위(기초·지하·역전지붕)의 표준.', '["비교·암기 — EPS(값싸고 범용, 물 먹음) ↔ XPS(물에 강함, 장기 성능 저하 있음) — ''젖는 곳은 XPS''."]'::jsonb, false),
  ('ee91441f-5250-533b-83b1-f81d1343b75b'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재유기질', '경질우레탄폼', '발포 우레탄 판·현장 발포. 열전도율 매우 낮음(고성능) — 두께 제약 부위, 화재 시 유독가스 주의.', '[]'::jsonb, false),
  ('57006859-ec17-535d-b4ba-7f5a0c7a3e00'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재유기질', '페놀폼 (PF보드)', '페놀 수지 발포판. 유기질 중 최상급 단열 성능+준불연 등급 확보 제품 — 최근 외단열 주류로 부상. ※등급 확인.', '[]'::jsonb, true),
  ('59d8189f-f5a2-5a32-81c9-5aadce3ac8f2'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재무기질', '글라스울', '유리 섬유 단열재. 불연·흡음 우수·경제적 — 경량 벽체·천장 충전용. 습기에 처지면 성능 저하(방습 조치).', '[]'::jsonb, false),
  ('78ddc457-2ac1-599d-a503-4963b981b3db'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재무기질', '미네랄울 (암면)', '암석 용융 섬유 단열재. 불연·내열 최고 — 내화 구획·설비 단열/외단열 화재 확산 방지 층.', '[]'::jsonb, false),
  ('ade0f286-480a-5a4e-9950-e1980b649cfa'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재무기질', '펄라이트', '진주암 팽창 경량 골재. 단열 모르타르·충전 단열재.', '[]'::jsonb, false),
  ('b2f6191c-dc62-5a6c-b971-d4c15f2c2abf'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재무기질', '셀룰로오스단열재', '폐지 섬유+난연 처리 충전 단열재. 친환경·틈새 충전(뿜칠).', '[]'::jsonb, false),
  ('5536ae42-cd79-55e9-8824-dad6f4616def'::uuid, '3장 · 7절 · 단열외벽마감 · 단열재무기질', '진공단열재 (VIP)', '심재를 진공 밀봉한 초고성능 단열재. 같은 성능을 1/5 두께로 — 고가, 타공·파손 시 성능 상실.', '[]'::jsonb, false),
  ('e8d01fec-1a69-50f6-83ce-a39e5baa0004'::uuid, '3장 · 7절 · 단열외벽마감 · 열성능지표', '열전도율', '재료 자체가 열을 전달하는 정도(W/mK). 재료의 고유 물성 — 작을수록 좋은 단열재.', '[]'::jsonb, false),
  ('7bd014b9-bd1b-5a54-ac42-727531b9b5d0'::uuid, '3장 · 7절 · 단열외벽마감 · 열성능지표', '열관류율 (U값)', '벽체 구성 전체(여러 층+표면)를 통과하는 열량(W/㎡K). 작을수록 단열 우수 — 부위·지역별 법정 기준값 존재. ※기준 확인.', '["비교·암기 — 열전도율(재료 한 가지의 성질) ↔ 열관류율(벽 전체의 성적표) — 단골 비교. 열저항(R)은 관류율의 역수 개념."]'::jsonb, true),
  ('c44736b0-0d4d-5a63-a186-c519da241643'::uuid, '3장 · 7절 · 단열외벽마감 · 열성능지표', '열저항 (R값)', '열 흐름에 대한 저항(두께/열전도율). 각 층의 R을 더해 벽 전체 성능을 계산 — 두꺼울수록, 전도율 낮을수록 큼.', '[]'::jsonb, false),
  ('75ebe0a1-3e9f-56a0-be98-ea981bd0aba0'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '내단열 · 중단열 · 외단열', '단열재 위치에 따른 구분. 내단열: 실내측(시공 쉬움, 열교·내부결로 취약). 중단열: 벽체 중간(공간쌓기). 외단열: 실외측(열교 차단·결로 유리·구조체 보호).', '["비교·암기 — ''이불을 안에 입냐 밖에 입냐'' — 외단열이 성능 원칙, 내단열은 시공 편의. 법규도 외단열 지향."]'::jsonb, false),
  ('0fd2039b-d80f-50fe-8eb1-a88649fa1976'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '열교 (냉교)', '단열이 끊긴 부위로 열이 집중해서 새는 통로(발코니 슬래브, 창 주위, 구조 접합부).', '["결과: 열손실+그 부위 표면온도 저하 — 결로·곰팡이. 대책: 단열 연속, 열차단재(단열 앵커·구조 단열재)."]'::jsonb, false),
  ('efa5c109-c401-53e4-803e-5fb6bd3f21c6'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '결로 (표면·내부)', '습한 공기가 노점온도 이하 표면·내부에서 물로 맺히는 현상.', '["표면결로: 벽·유리 표면(곰팡이). 내부결로: 벽체 속(단열재 젖음·구조 손상 — 더 위험).", "대책 3중 세트: 단열(표면온도 올림)+방습(수증기 차단)+환기(습기 배출) — 셋 중 하나만으로는 부족."]'::jsonb, false),
  ('b904e14e-3cf6-5077-bdd7-678f088ea30e'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '노점온도', '공기가 냉각되어 수증기가 응결을 시작하는 온도. 습도가 높을수록 노점이 높아 결로 쉬움.', '[]'::jsonb, false),
  ('3ddd3c2f-82c7-5e45-aa05-c662e0c264b0'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '방습층', '수증기의 벽체 내 침입을 막는 층(PE 필름 등). 실내측(따뜻한 쪽)에 설치가 원칙.', '["비교·암기 — ''방습층은 따뜻한 쪽에'' — 내부결로 방지의 방향 원칙. 외측은 오히려 습기를 내보내는 투습 구성이 이상적."]'::jsonb, false),
  ('15ff7bf6-5a2c-597a-a3ae-b427b86ab0f4'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '투습 · 투습저항', '수증기가 재료를 통과하는 성질과 그 저항. 외측은 투습(습기 배출), 내측은 방습이 이상적 구성.', '[]'::jsonb, false),
  ('a29f7069-8de2-5298-94c8-0ad97e17c4e1'::uuid, '3장 · 7절 · 단열외벽마감 · 단열위치와열교결로', '기밀성능', '틈새로 공기가 새는 정도. 기밀할수록 에너지·결로·소음에 유리 — 대신 계획 환기 필수.', '["패시브하우스의 핵심 지표 — ''단열 다음은 기밀''."]'::jsonb, false),
  ('22c2115a-4b26-5591-b70d-d7129cbe901c'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '외단열미장마감 (EIFS·드라이비트)', '단열재를 외벽에 접착·고정하고 메시+미장으로 마감하는 외단열 시스템.', '["저렴·외단열 효과. 약점: 충격에 약함, 가연성 단열재 사용 시 화재 수직 확산 — 대형 화재 사고의 쟁점(준불연 이상 사용 의무화 흐름 ※확인)."]'::jsonb, true),
  ('d2c44a3b-febe-58ac-8f34-6152a41eb609'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '준불연 · 난연 · 불연 재료', '화재 성능 등급: 불연(콘크리트·유리·암면) > 준불연 > 난연, 외벽 마감재·단열재의 등급 규제 — 층수·용도별 기준. ※확인.', '["대형 외벽 화재 이후 강화된 규제의 핵심 용어 — 안전 직무와의 연결 포인트."]'::jsonb, true),
  ('be2ccf41-44a8-5998-906a-3bacde47547d'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '화재확산방지구조', '외벽 층간에 불연 띠(미네랄울 등)를 둘러 수직 화재 확산을 차단하는 구조. 가연성 외벽 마감의 보완 장치. ※설치 기준 확인.', '[]'::jsonb, true),
  ('25d8ddc4-0b5e-537a-bd10-929944ceca6e'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '알루미늄복합패널', '알루미늄 두 장 사이에 심재를 넣은 샌드위치 판. 평활·경량 외장재.', '["심재가 가연성(PE)이면 화재 확산 위험 — 불연 심재 요구가 규제 흐름. ※확인."]'::jsonb, true),
  ('cd8410fa-d68c-5eef-97f1-88b1cefff87b'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '샌드위치패널', '강판 두 장+단열 심재(EPS·우레탄·글라스울)의 조립식 벽·지붕 패널. 공장·창고의 표준.', '["EPS 심재 패널의 화재 취약성이 공장 화재 대형화의 주요 원인으로 지목(불연 심재 규제 강화 ※확인)."]'::jsonb, true),
  ('77c9b6c2-676c-5e34-88b4-5207d4d02279'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '금속사이딩', '금속판 성형 외벽 마감재(가로·세로 판붙임). 경량·건식 — 리모델링 외벽에 많음.', '[]'::jsonb, false),
  ('def5f798-c1b2-549d-8b48-822a5332f43f'::uuid, '3장 · 7절 · 단열외벽마감 · 외벽마감시스템', '석재 · 세라믹 외장패널', '석재(건식 공법)·세라믹 대형 판을 오픈조인트·파스너로 거는 고급 외장. 통기층(레인스크린) 구성과 결합.', '[]'::jsonb, false)
) as v(id, section, title, definition, points, flagged)
cross join (select id from auth.users limit 1) as u;
